INSERT INTO metier (id, nom, nom_cle, description, bonus_brut, artisanat_brut, peut_fabriquer, artisanat_texte, test_brut, test_carac_1_id, test_carac_2_id, equipement_brut, avantage_brut, origine, source_ref) VALUES ('metiers/acrobate', 'Acrobate', 'acrobate', 'L’acrobate est un artiste du mouvement et de la souplesse, capable d’enchaîner les sauts et roulades avec une précision remarquable. On le trouve souvent dans les troupes itinérantes, les cirques ou au service de nobles pour leurs divertissements. Ce métier demande une discipline physique rigoureuse et un sens du spectacle développé.', '+3% Esquive, +3% Réflexe', 'Rien', 0, NULL, NULL, NULL, NULL, 'Rien', 'Pour ne pas tomber au sol, …', 'docs_typees', 'Google Doc « MÉTIER » › Acrobate › champs de la page');
INSERT INTO metier (id, nom, nom_cle, description, bonus_brut, artisanat_brut, peut_fabriquer, artisanat_texte, test_brut, test_carac_1_id, test_carac_2_id, equipement_brut, avantage_brut, origine, source_ref) VALUES ('metiers/agriculteur', 'Agriculteur', 'agriculteur', 'L’agriculteur est le cœur battant des campagnes, travaillant la terre pour nourrir les populations. Son quotidien est rythmé par les saisons, la météo et la patience. Il connaît les cycles naturels, les graines et la valeur du travail manuel.', '+3% Connaissance, +3% Vigueur', 'Rien', 0, NULL, NULL, NULL, NULL, 'Faux en fer (Arme)', 'Information sur les plantes cultivables, …', 'docs_typees', 'Google Doc « MÉTIER » › Agriculteur › champs de la page');
INSERT INTO metier (id, nom, nom_cle, description, bonus_brut, artisanat_brut, peut_fabriquer, artisanat_texte, test_brut, test_carac_1_id, test_carac_2_id, equipement_brut, avantage_brut, origine, source_ref) VALUES ('metiers/alchimiste', 'Alchimiste', 'alchimiste', 'L’alchimiste est un érudit des mélanges et des transformations, cherchant sans relâche à comprendre les propriétés cachées des matériaux. Il passe ses journées entre fourneaux, grimoires et fioles fumantes. Son savoir est précieux, mais parfois dangereux pour qui manipule sans précaution.', '+3% Connaissance', 'Peut fabriquer les fioles, philtres, l’alchimie primitive [INTELLIGENCE + PERCEPTION]', 1, 'Peut fabriquer les fioles, philtres, l’alchimie primitive', 'INTELLIGENCE + PERCEPTION', 'intelligence', 'perception', 'Kit d’alchimiste de base', 'Identifier une fiole, philtre ou poison, …', 'docs_typees', 'Google Doc « MÉTIER » › Alchimiste › champs de la page');
INSERT INTO metier (id, nom, nom_cle, description, bonus_brut, artisanat_brut, peut_fabriquer, artisanat_texte, test_brut, test_carac_1_id, test_carac_2_id, equipement_brut, avantage_brut, origine, source_ref) VALUES ('metiers/ange-gardien', 'Ange-gardien', 'ange-gardien', 'Le nom pourrait faire croire à un métier compliqué mais il est plus simple qu’on ne le croit, il s’agit d’une personne qui raccompagne les gens ivre chez eux ou les gens qui auraient peur d’emprunter les rues la nuit. Il prend des risques pour protéger et accompagner.', '+3% Diplomatie OU Intimidation, +3% Parade OU Esquive', 'Rien', 0, NULL, NULL, NULL, NULL, 'Rien', 'Maîtriser quelqu’un, …', 'docs_typees', 'Google Doc « MÉTIER » › Ange-gardien › champs de la page');
INSERT INTO metier (id, nom, nom_cle, description, bonus_brut, artisanat_brut, peut_fabriquer, artisanat_texte, test_brut, test_carac_1_id, test_carac_2_id, equipement_brut, avantage_brut, origine, source_ref) VALUES ('metiers/apothicaire', 'Apothicaire', 'apothicaire', 'L’apothicaire prépare remèdes, onguents et mélanges curatifs à partir d’ingrédients naturels. Il connaît les herbes, les plantes et leurs effets sur le corps. Son échoppe est souvent fréquentée par malades, voyageurs et sages-femmes.', '+3% Vigueur', 'Peut fabriquer les remèdes, huiles, l’alchimie primitive [VOLONTÉ + PERCEPTION]', 1, 'Peut fabriquer les remèdes, huiles, l’alchimie primitive', 'VOLONTÉ + PERCEPTION', 'volonte', 'perception', 'Kit d’alchimie de base', 'Identifier un remède, philtre, huile, …', 'docs_typees', 'Google Doc « MÉTIER » › Apothicaire › champs de la page');
INSERT INTO metier (id, nom, nom_cle, description, bonus_brut, artisanat_brut, peut_fabriquer, artisanat_texte, test_brut, test_carac_1_id, test_carac_2_id, equipement_brut, avantage_brut, origine, source_ref) VALUES ('metiers/archeologue', 'Archéologue', 'archeologue', 'L’archéologue explore les ruines anciennes pour en extraire connaissances, artefacts et traces des civilisations passées. Il combine savoir académique et sens de l’aventure. Son métier le mène souvent dans des lieux dangereux ou isolés, où patience et méthode sont essentielles.', '+3% Connaissance, +3% Orientation', 'Rien', 0, NULL, NULL, NULL, NULL, 'Parchemin vierge, Encrier', 'Identifier ce qui est ancien, en ruines, …', 'docs_typees', 'Google Doc « MÉTIER » › Archéologue › champs de la page');
INSERT INTO metier (id, nom, nom_cle, description, bonus_brut, artisanat_brut, peut_fabriquer, artisanat_texte, test_brut, test_carac_1_id, test_carac_2_id, equipement_brut, avantage_brut, origine, source_ref) VALUES ('metiers/armurier', 'Armurier', 'armurier', 'L’armurier conçoit, entretient et répare les armures destinées aux soldats, mercenaires, chevaliers ou tout autres personnes pouvant se le permettre. Son travail exige force, précision et une compréhension fine des matériaux. Il est indispensable dans toute cité ou garnison soucieuse de sa protection.', '+3% Parade, +1AP donné par les armures métalliques fabriquer', 'Armure et bouclier en métal [FORCE + INTELLIGENCE]', 1, 'Armure et bouclier en métal', 'FORCE + INTELLIGENCE', 'force', 'intelligence', 'Kit de réparation d’armure', 'Identifier une armure, …', 'docs_typees', 'Google Doc « MÉTIER » › Armurier › champs de la page');
INSERT INTO metier (id, nom, nom_cle, description, bonus_brut, artisanat_brut, peut_fabriquer, artisanat_texte, test_brut, test_carac_1_id, test_carac_2_id, equipement_brut, avantage_brut, origine, source_ref) VALUES ('metiers/artisan', 'Artisan', 'artisan', 'L’artisan est un travailleur habile spécialisé dans un savoir-faire précis, qu’il s’agisse du bois, du cuir, de la pierre ou d’un autre matériau. Il façonne des objets utiles ou décoratifs, fruits d’un long apprentissage. Son rôle est central dans la vie quotidienne des villages comme des cités.', 'Le malus de l’artisanat du à la non-spécialisation est réduit à 20% au lieu de 40%', 'Un peu tout', 1, 'Un peu tout', NULL, NULL, NULL, 'Maillet en fer', NULL, 'docs_typees', 'Google Doc « MÉTIER » › Artisan › champs de la page');
INSERT INTO metier (id, nom, nom_cle, description, bonus_brut, artisanat_brut, peut_fabriquer, artisanat_texte, test_brut, test_carac_1_id, test_carac_2_id, equipement_brut, avantage_brut, origine, source_ref) VALUES ('metiers/assassin', 'Assassin', 'assassin', 'L’assassin est un professionnel du meurtre silencieux, entraîné pour frapper vite et disparaître sans laisser de traces. Il opère souvent pour des seigneurs, des guildes ou des clients anonymes. Sa vie est faite de secrets, de risques et d’une discipline froide et méthodique.', '+3% Ruse, +3% Sabotage', 'Rien', 0, NULL, NULL, NULL, NULL, 'Dague/Poignard en acier (Arme)', '…', 'docs_typees', 'Google Doc « MÉTIER » › Assassin › champs de la page');
INSERT INTO metier (id, nom, nom_cle, description, bonus_brut, artisanat_brut, peut_fabriquer, artisanat_texte, test_brut, test_carac_1_id, test_carac_2_id, equipement_brut, avantage_brut, origine, source_ref) VALUES ('metiers/astronome', 'Astronome', 'astronome', 'L’astronome observe le ciel pour comprendre les mouvements des étoiles, des saisons et du temps. Souvent solitaire, il passe ses nuits à étudier les astres et à prendre des notes précises. Ses conseils sont précieux pour les navigateurs et certains érudits.', '+3% Orientation, +3% Observation', 'Rien', 0, NULL, NULL, NULL, NULL, 'Longue-vue', 'Se repérer la nuit, sur la mer, identifier la saison, …', 'docs_typees', 'Google Doc « MÉTIER » › Astronome › champs de la page');
INSERT INTO metier (id, nom, nom_cle, description, bonus_brut, artisanat_brut, peut_fabriquer, artisanat_texte, test_brut, test_carac_1_id, test_carac_2_id, equipement_brut, avantage_brut, origine, source_ref) VALUES ('metiers/aventurier', 'Aventurier', 'aventurier', 'L’aventurier parcourt le monde en quête d’exploration, de découvertes ou de fortune. Il mène une vie imprévisible, faite de rencontres, de dangers et de décisions rapides. Sa polyvalence et son audace en font un voyageur atypique.', '+3% Vie en nature, +3% Survie', 'Rien', 0, NULL, NULL, NULL, NULL, 'Grand sac à dos', '…', 'docs_typees', 'Google Doc « MÉTIER » › Aventurier › champs de la page');
INSERT INTO metier (id, nom, nom_cle, description, bonus_brut, artisanat_brut, peut_fabriquer, artisanat_texte, test_brut, test_carac_1_id, test_carac_2_id, equipement_brut, avantage_brut, origine, source_ref) VALUES ('metiers/bijoutier', 'Bijoutier', 'bijoutier', 'Le bijoutier façonne des ornements précieux à partir d‘alliage et de pierres. Son travail demande minutie, goût et une patience extrême. Ces objets permettent d’avoir beaucoup de bonus.', '+3% Distinction', 'Peut fabriquer les accessoires ou les désenchanter [VOLONTÉ + PERCEPTION]', 1, 'Peut fabriquer les accessoires ou les désenchanter', 'VOLONTÉ + PERCEPTION', 'volonte', 'perception', 'Rien', 'Identifier un accessoire avant de le porter, …', 'docs_typees', 'Google Doc « MÉTIER » › Bijoutier › champs de la page');
INSERT INTO metier (id, nom, nom_cle, description, bonus_brut, artisanat_brut, peut_fabriquer, artisanat_texte, test_brut, test_carac_1_id, test_carac_2_id, equipement_brut, avantage_brut, origine, source_ref) VALUES ('metiers/boucher', 'Boucher', 'boucher', 'Le boucher abat, découpe et prépare la viande destinée aux marchés et aux foyers. Son métier demande force, précision et un respect strict de l’hygiène. Souvent au cœur des villages, il connaît bien la population qu’il nourrit.', '+2% Arme lourde', 'Transformer des carcasses en viande consommable [FORCE + VOLONTÉ]', 1, 'Transformer des carcasses en viande consommable', 'FORCE + VOLONTÉ', 'force', 'volonte', 'Couperet en acier (1 main) (Arme)', '…', 'docs_typees', 'Google Doc « MÉTIER » › Boucher › champs de la page');
INSERT INTO metier (id, nom, nom_cle, description, bonus_brut, artisanat_brut, peut_fabriquer, artisanat_texte, test_brut, test_carac_1_id, test_carac_2_id, equipement_brut, avantage_brut, origine, source_ref) VALUES ('metiers/bouffon', 'Bouffon', 'bouffon', 'Le bouffon divertit la noblesse grâce à son humour, ses acrobaties et parfois une franchise bien dosée. Derrière son apparence frivole, il observe et comprend les humeurs des puissants. Sa langue peut être aussi affutée que son esprit.', '+3% Manipulation, +3% Esquive', 'Rien', 0, NULL, NULL, NULL, NULL, 'Cloche portable', 'Pour attirer l’attention, …', 'docs_typees', 'Google Doc « MÉTIER » › Bouffon › champs de la page');
INSERT INTO metier (id, nom, nom_cle, description, bonus_brut, artisanat_brut, peut_fabriquer, artisanat_texte, test_brut, test_carac_1_id, test_carac_2_id, equipement_brut, avantage_brut, origine, source_ref) VALUES ('metiers/boulanger', 'Boulanger', 'boulanger', 'Le boulanger pétrit, façonne et cuit le pain qui nourrit chaque foyer. Son travail commence avant l’aube et demande endurance et précision. Son fournil est souvent un lieu chaleureux où se croisent habitants et voyageurs. Ils sont également capables de confectionner les golems de pains avec l’aide d’un cœur énergique.', '+2% Athlétisme', 'Fabriquer du pain, ce dernier peut redonner 5 santé si consommé [FORCE + PERCEPTION]', 1, 'Fabriquer du pain, ce dernier peut redonner 5 santé si consommé', 'FORCE + PERCEPTION', 'force', 'perception', 'Pelle en acier (Arme)', 'Identifier le pain, parler avec le peuple, …', 'docs_typees', 'Google Doc « MÉTIER » › Boulanger › champs de la page');
INSERT INTO metier (id, nom, nom_cle, description, bonus_brut, artisanat_brut, peut_fabriquer, artisanat_texte, test_brut, test_carac_1_id, test_carac_2_id, equipement_brut, avantage_brut, origine, source_ref) VALUES ('metiers/bourreau', 'Bourreau', 'bourreau', 'Le bourreau exécute les sentences les plus sévères décidées par la justice. Son rôle exige une certaine froideur, mais aussi une rigueur absolue dans l’application de la loi. Bien qu’il inspire la crainte, son métier est essentiel pour exécuter les plus grandes crapules du monde.', '+3% Intimidation, +2% Arme lourde', 'Rien', 0, NULL, NULL, NULL, NULL, 'Couperet en acier (2 mains) (Arme)', '…', 'docs_typees', 'Google Doc « MÉTIER » › Bourreau › champs de la page');
INSERT INTO metier (id, nom, nom_cle, description, bonus_brut, artisanat_brut, peut_fabriquer, artisanat_texte, test_brut, test_carac_1_id, test_carac_2_id, equipement_brut, avantage_brut, origine, source_ref) VALUES ('metiers/bousier', 'Bousier', 'bousier', 'Le bousier collecte, trie et prépare les déjections d’animaux afin de produire engrais, combustibles ou matériaux spécifiques. Ce travail ingrat demande robustesse et peu de sensibilité aux odeurs. Malgré son image peu valorisée, il joue un rôle essentiel dans certaines économies rurales.', '+3% Survie, +3% Vigueur', 'Rien', 0, NULL, NULL, NULL, NULL, 'Pelle en acier (Arme)', 'Résister à un environnement sale, …', 'docs_typees', 'Google Doc « MÉTIER » › Bousier › champs de la page');
INSERT INTO metier (id, nom, nom_cle, description, bonus_brut, artisanat_brut, peut_fabriquer, artisanat_texte, test_brut, test_carac_1_id, test_carac_2_id, equipement_brut, avantage_brut, origine, source_ref) VALUES ('metiers/brasseur', 'Brasseur', 'brasseur', 'Le brasseur fabrique bières, cervoises et autres boissons fermentées appréciées dans les tavernes. Il maîtrise les techniques de fermentation et les recettes locales. Sa production est souvent au cœur de la convivialité d’un village.', '+2% Distinction, +2% Vigueur', 'Fabriquer de l’alcool, ce dernier peut redonner 5 chakra si consommé [VOLONTÉ + PERCEPTION]', 1, 'Fabriquer de l’alcool, ce dernier peut redonner 5 chakra si consommé', 'VOLONTÉ + PERCEPTION', 'volonte', 'perception', 'Tonnelet en bois', 'Identifier un alcool, …', 'docs_typees', 'Google Doc « MÉTIER » › Brasseur › champs de la page');
INSERT INTO metier (id, nom, nom_cle, description, bonus_brut, artisanat_brut, peut_fabriquer, artisanat_texte, test_brut, test_carac_1_id, test_carac_2_id, equipement_brut, avantage_brut, origine, source_ref) VALUES ('metiers/bucheron', 'Bûcheron', 'bucheron', 'Le bûcheron coupe, transporte et prépare le bois nécessaire à la construction, au chauffage et à l’artisanat. Sa vie se déroule au rythme des forêts et du dur labeur. Il est celui qui reconnaît tout type de bois mais également de les transformer en planche utilisable.', '+2% Stabilité, +2% Athlétisme', 'Peut faire des planches et les différents bois [FORCE  + VOLONTÉ]', 1, 'Peut faire des planches et les différents bois', 'FORCE  + VOLONTÉ', 'force', 'volonte', 'Hache en acier (Arme)', 'Identifier des arbres, planches, bois, …', 'docs_typees', 'Google Doc « MÉTIER » › Bûcheron › champs de la page');
INSERT INTO metier (id, nom, nom_cle, description, bonus_brut, artisanat_brut, peut_fabriquer, artisanat_texte, test_brut, test_carac_1_id, test_carac_2_id, equipement_brut, avantage_brut, origine, source_ref) VALUES ('metiers/cartographe', 'Cartographe', 'cartographe', 'Le cartographe explore territoires et routes pour en dresser des cartes précises et fiables. Il allie observation, mesure et sens de l’orientation. Ses créations sont indispensables aux voyageurs, aux armées et aux marchands.', '+3% Orientation, +2% Observation', 'Rien', 0, NULL, NULL, NULL, NULL, 'Boussole, Carte du monde', 'Se repérer sur une carte, …', 'docs_typees', 'Google Doc « MÉTIER » › Cartographe › champs de la page');
INSERT INTO metier (id, nom, nom_cle, description, bonus_brut, artisanat_brut, peut_fabriquer, artisanat_texte, test_brut, test_carac_1_id, test_carac_2_id, equipement_brut, avantage_brut, origine, source_ref) VALUES ('metiers/charpentier', 'Charpentier', 'charpentier', 'Le charpentier façonne les structures en bois des maisons, ponts et navires. Son métier demande précision, sens de l’équilibre et connaissance des essences de bois. Il est souvent considéré comme l’un des piliers de la construction locale.', '+2% Athlétisme, +2% Arme lourde, +2% Stabilité', 'Peut aider à la construction d’objets en bois [FORCE + AGILITÉ]', 1, 'Peut aider à la construction d’objets en bois', 'FORCE + AGILITÉ', 'force', 'agilite', 'Maillet en fer', '…', 'docs_typees', 'Google Doc « MÉTIER » › Charpentier › champs de la page');
INSERT INTO metier (id, nom, nom_cle, description, bonus_brut, artisanat_brut, peut_fabriquer, artisanat_texte, test_brut, test_carac_1_id, test_carac_2_id, equipement_brut, avantage_brut, origine, source_ref) VALUES ('metiers/chasseur', 'Chasseur', 'chasseur', 'Le chasseur traque le gibier pour nourrir les communautés ou fournir des ressources rares. Il connaît les terrains, les traces et les habitudes des animaux. Son métier exige patience, discrétion et une excellente condition physique.', '+2% Arc OU Arbalète', 'Rien', 0, NULL, NULL, NULL, NULL, 'Arc ou Arbalète en acier (Arme)', 'Pour chasser, faire un double jet de butin pour chasser, …', 'docs_typees', 'Google Doc « MÉTIER » › Chasseur › champs de la page');
INSERT INTO metier (id, nom, nom_cle, description, bonus_brut, artisanat_brut, peut_fabriquer, artisanat_texte, test_brut, test_carac_1_id, test_carac_2_id, equipement_brut, avantage_brut, origine, source_ref) VALUES ('metiers/chaudronnier', 'Chaudronnier', 'chaudronnier', 'Le chaudronnier travaille le métal, il est celui qui est capable de faire les différents alliages grâce aux minerais mais il est également celui qui s’occupe du chaudron de brai brouillant, très utilisé dans les châteaux pour la défense.', '+3% Concentration', 'Peut faire des lingots à partir de minerais [FORCE  + VOLONTÉ]', 1, 'Peut faire des lingots à partir de minerais', 'FORCE  + VOLONTÉ', 'force', 'volonte', 'Rien', '…', 'docs_typees', 'Google Doc « MÉTIER » › Chaudronnier › champs de la page');
INSERT INTO metier (id, nom, nom_cle, description, bonus_brut, artisanat_brut, peut_fabriquer, artisanat_texte, test_brut, test_carac_1_id, test_carac_2_id, equipement_brut, avantage_brut, origine, source_ref) VALUES ('metiers/chef-cuisinier', 'Chef-cuisinier', 'chef-cuisinier', 'Le chef-cuisinier dirige les cuisines et crée des plats raffinés ou nourrissants selon les moyens du lieu où il travaille. Il connaît les ingrédients, les saveurs et les méthodes de préparation les plus efficaces. Son savoir-faire fait de lui une figure incontournable des tavernes comme des palais.', '+2% Connaissance, +2% Distinction', 'Peut cuisiner [PERCEPTION + INTELLIGENCE]', 1, 'Peut cuisiner', 'PERCEPTION + INTELLIGENCE', 'perception', 'intelligence', 'Petit sac de sel', 'Cuisine, reconnaître un plat, …', 'docs_typees', 'Google Doc « MÉTIER » › Chef-cuisinier › champs de la page');
INSERT INTO metier (id, nom, nom_cle, description, bonus_brut, artisanat_brut, peut_fabriquer, artisanat_texte, test_brut, test_carac_1_id, test_carac_2_id, equipement_brut, avantage_brut, origine, source_ref) VALUES ('metiers/comedien', 'Comédien', 'comedien', 'Le comédien donne vie à des histoires, jouant sur scène pour divertir, émouvoir ou instruire le public. Sa voix, son expression et sa maîtrise du geste sont ses outils principaux. Il voyage souvent avec une troupe, allant de ville en ville selon les saisons.', '+5% dans une compétence sociale au choix', 'Rien', 0, NULL, NULL, NULL, NULL, 'Rien', 'Attirer l’attention, …', 'docs_typees', 'Google Doc « MÉTIER » › Comédien › champs de la page');
INSERT INTO metier (id, nom, nom_cle, description, bonus_brut, artisanat_brut, peut_fabriquer, artisanat_texte, test_brut, test_carac_1_id, test_carac_2_id, equipement_brut, avantage_brut, origine, source_ref) VALUES ('metiers/coursier', 'Coursier', 'coursier', 'Le coursier transporte rapidement messages, colis ou ordres officiels entre différentes localités. Toujours en mouvement, il traverse routes, plaines et parfois territoires hostiles. Vitesse, fiabilité et prise de risques, voilà ce qui définit un coursier.', '+1 INI, +2% Athlétisme OU Équilibre', 'Rien', 0, NULL, NULL, NULL, NULL, 'Rien', 'Courir dans une direction, …', 'docs_typees', 'Google Doc « MÉTIER » › Coursier › champs de la page');
INSERT INTO metier (id, nom, nom_cle, description, bonus_brut, artisanat_brut, peut_fabriquer, artisanat_texte, test_brut, test_carac_1_id, test_carac_2_id, equipement_brut, avantage_brut, origine, source_ref) VALUES ('metiers/couturier', 'Couturier', 'couturier', 'Le couturier confectionne vêtements et parures en fonction des besoins de la population ou des exigences des nobles. Sa précision et son sens du style dictent la qualité de ses créations. Dans les villes, son atelier est souvent un lieu fréquenté.', '+3% Connaissance', 'Peut faire des vêtements, robe, … [PERCEPTION  + INTELLIGENCE]', 1, 'Peut faire des vêtements, robe, …', 'PERCEPTION  + INTELLIGENCE', 'perception', 'intelligence', 'Vêtement de voyage (Armure)', 'Identifier un vêtement, identifier une provenance d’un tissu, …', 'docs_typees', 'Google Doc « MÉTIER » › Couturier › champs de la page');
INSERT INTO metier (id, nom, nom_cle, description, bonus_brut, artisanat_brut, peut_fabriquer, artisanat_texte, test_brut, test_carac_1_id, test_carac_2_id, equipement_brut, avantage_brut, origine, source_ref) VALUES ('metiers/couvreur', 'Couvreur', 'couvreur', 'Le couvreur répare et installe les toits, qu''ils soient en tuiles, ardoises ou bois. Son métier l''amène souvent à travailler en hauteur, exposé aux intempéries. Il contribue directement à la sécurité et à la solidité des habitations.', '+6% Stabilité', 'Peut aider à la construction de toit [FORCE + AGILITÉ]', 1, 'Peut aider à la construction de toit', 'FORCE + AGILITÉ', 'force', 'agilite', 'Rien', 'Ne pas tomber d’un toit, …', 'docs_typees', 'Google Doc « MÉTIER » › Couvreur › champs de la page');
INSERT INTO metier (id, nom, nom_cle, description, bonus_brut, artisanat_brut, peut_fabriquer, artisanat_texte, test_brut, test_carac_1_id, test_carac_2_id, equipement_brut, avantage_brut, origine, source_ref) VALUES ('metiers/crieur', 'Crieur', 'crieur', 'Le crieur public annonce nouvelles, édits et événements sur les places des villes. Sa voix puissante est son principal outil de travail. Il est parfois la seule source d’information officielle pour les habitants les plus isolés.', '+3% Diplomatie, +3% Connaissance', 'Rien', 0, NULL, NULL, NULL, NULL, 'Cloche portable', 'Pour attirer l’attention, …', 'docs_typees', 'Google Doc « MÉTIER » › Crieur › champs de la page');
INSERT INTO metier (id, nom, nom_cle, description, bonus_brut, artisanat_brut, peut_fabriquer, artisanat_texte, test_brut, test_carac_1_id, test_carac_2_id, equipement_brut, avantage_brut, origine, source_ref) VALUES ('metiers/croise', 'Croisé', 'croise', 'Le croisé est un combattant engagé dans une cause religieuse, souvent envoyé loin de sa terre natale. Son devoir prime sur son confort, et il suit les ordres de ses supérieurs sans hésitation. Ses voyages sont marqués par les conflits et les épreuves spirituelles. Il existe différents rang militaires chez les croisés, il sera important de le déterminer car ça peut impliquer beaucoup de choses.', '+3% Arme lourde OU Arme légère OU Arc OU Arbalète OU Magie OU Concentration', 'Rien', 0, NULL, NULL, NULL, NULL, 'Rien', 'Reconnaître un grade, reconnaître une guilde, …', 'docs_typees', 'Google Doc « MÉTIER » › Croisé › champs de la page');
INSERT INTO metier (id, nom, nom_cle, description, bonus_brut, artisanat_brut, peut_fabriquer, artisanat_texte, test_brut, test_carac_1_id, test_carac_2_id, equipement_brut, avantage_brut, origine, source_ref) VALUES ('metiers/eclaireur', 'Éclaireur', 'eclaireur', 'L’éclaireur précède les groupes armés pour repérer dangers, terrains et déplacements ennemis. Agile et discret, il passe souvent inaperçu. Il joue un rôle essentiel dans la stratégie militaire et la survie de son groupe.', '+2% Observation OU Distinction, Possède une parade/esquive en plus en vigilance', 'Rien', 0, NULL, NULL, NULL, NULL, 'Rien', 'Observer une zone, …', 'docs_typees', 'Google Doc « MÉTIER » › Éclaireur › champs de la page');
INSERT INTO metier (id, nom, nom_cle, description, bonus_brut, artisanat_brut, peut_fabriquer, artisanat_texte, test_brut, test_carac_1_id, test_carac_2_id, equipement_brut, avantage_brut, origine, source_ref) VALUES ('metiers/ecrivain', 'Écrivain', 'ecrivain', 'L’écrivain compose récits, chroniques et histoires destinées au public ou aux bibliothèques. Son imagination comme sa maîtrise du langage définissent son talent. Certains écrivent pour de riches mécènes tandis que d’autres voyagent à la recherche d’inspiration.', '+3% Connaissance', 'Peut écrire des livres magiques [PERCEPTION  + INTELLIGENCE]', 1, 'Peut écrire des livres magiques', 'PERCEPTION  + INTELLIGENCE', 'perception', 'intelligence', 'Plume, encrier', 'Identifier un livre, …', 'docs_typees', 'Google Doc « MÉTIER » › Écrivain › champs de la page');
INSERT INTO metier (id, nom, nom_cle, description, bonus_brut, artisanat_brut, peut_fabriquer, artisanat_texte, test_brut, test_carac_1_id, test_carac_2_id, equipement_brut, avantage_brut, origine, source_ref) VALUES ('metiers/eleveur', 'Éleveur (choix animal)', 'eleveur-choix-animal', 'L’éleveur consacre son temps à soigner, nourrir et faire prospérer une espèce animale particulière. Il connaît leurs habitudes, leurs besoins et leurs comportements. Son travail est indispensable aux marchés, aux soldats et aux artisans qui utilisent ces animaux. Il est important de déterminer l’animal.', '+3% Dressage, Peut avoir un animal qui correspond au métier', 'Rien', 0, NULL, NULL, NULL, NULL, 'Fouet en fer (Arme)', 'Comprendre le comportement animal, …', 'docs_typees', 'Google Doc « MÉTIER » › Éleveur (choix animal) › champs de la page');
INSERT INTO metier (id, nom, nom_cle, description, bonus_brut, artisanat_brut, peut_fabriquer, artisanat_texte, test_brut, test_carac_1_id, test_carac_2_id, equipement_brut, avantage_brut, origine, source_ref) VALUES ('metiers/enchanteur', 'Enchanteur', 'enchanteur', 'L’enchanteur est un spécialiste des objets rares et des artefacts particuliers, capable d’y apposer des effets subtils ou des propriétés précieuses. Son savoir demande une grande précision et des années d’étude. Les nobles comme les aventuriers recherchent ses services pour améliorer leur équipement.', '+2% Connaissance, +2% Concentration OU Magie', 'Peut fabriquer des bâtons magiques et désenchanter des accessoires [PERCEPTION  + VOLONTÉ]', 1, 'Peut fabriquer des bâtons magiques et désenchanter des accessoires', 'PERCEPTION  + VOLONTÉ', 'perception', 'volonte', 'Rien', 'Reconnaître une gemme, un accessoire, un bâton, …', 'docs_typees', 'Google Doc « MÉTIER » › Enchanteur › champs de la page');
INSERT INTO metier (id, nom, nom_cle, description, bonus_brut, artisanat_brut, peut_fabriquer, artisanat_texte, test_brut, test_carac_1_id, test_carac_2_id, equipement_brut, avantage_brut, origine, source_ref) VALUES ('metiers/espion', 'Espion', 'espion', 'L’espion recueille des informations sensibles pour le compte d’un seigneur, d’une guilde ou d’un pays. Il se fond dans la foule, s’adapte à tous les milieux et manie l’art du mensonge. Son travail l’expose constamment au danger et à la méfiance.', '+3% Ruse, +3% Manipulation', 'Rien', 0, NULL, NULL, NULL, NULL, 'Rien', 'Se fondre dans la foule, …', 'docs_typees', 'Google Doc « MÉTIER » › Espion › champs de la page');
INSERT INTO metier (id, nom, nom_cle, description, bonus_brut, artisanat_brut, peut_fabriquer, artisanat_texte, test_brut, test_carac_1_id, test_carac_2_id, equipement_brut, avantage_brut, origine, source_ref) VALUES ('metiers/facteur', 'Facteur', 'facteur', 'Le facteur distribue lettres, messages et petits colis à travers villages et quartiers. Il connaît mieux que quiconque les familles et leurs habitudes. Sa présence régulière fait de lui un visage familier et souvent apprécié.', '+3% Athlétisme, +1 Vitesse au sol pour le sprint', 'Rien', 0, NULL, NULL, NULL, NULL, 'Grand sac à dos', '…', 'docs_typees', 'Google Doc « MÉTIER » › Facteur › champs de la page');
INSERT INTO metier (id, nom, nom_cle, description, bonus_brut, artisanat_brut, peut_fabriquer, artisanat_texte, test_brut, test_carac_1_id, test_carac_2_id, equipement_brut, avantage_brut, origine, source_ref) VALUES ('metiers/fauconnier', 'Fauconnier', 'fauconnier', 'Le fauconnier dresse, soigne et entraîne des oiseaux de chasse utilisés pour la capture de gibier ou la transmission de messages. Le lien qu’il tisse avec ses oiseaux est fondé sur la patience et la discipline. Il travaille généralement pour des nobles ou des chasseurs expérimentés.', '+3% Dressage, Peut avoir un faucon', 'Rien', 0, NULL, NULL, NULL, NULL, 'Rien', 'Comprendre le comportement des oiseaux, …', 'docs_typees', 'Google Doc « MÉTIER » › Fauconnier › champs de la page');
INSERT INTO metier (id, nom, nom_cle, description, bonus_brut, artisanat_brut, peut_fabriquer, artisanat_texte, test_brut, test_carac_1_id, test_carac_2_id, equipement_brut, avantage_brut, origine, source_ref) VALUES ('metiers/ferronnier', 'Ferronnier', 'ferronnier', 'Le ferronnier façonne outils, pièces métalliques et objets utilitaires indispensables à la vie quotidienne. Il travaille le fer avec force et précision, souvent dans un atelier enfumé et bruyant. Son savoir-faire soutient l’artisanat local dans son ensemble.', '+2% Arme lourde OU Arme légère', 'Peut faire des golems à partir d’alliage [FORCE  + INTELLIGENCE]', 1, 'Peut faire des golems à partir d’alliage', 'FORCE  + INTELLIGENCE', 'force', 'intelligence', 'Rien', 'Analyser un golem, …', 'docs_typees', 'Google Doc « MÉTIER » › Ferronnier › champs de la page');
INSERT INTO metier (id, nom, nom_cle, description, bonus_brut, artisanat_brut, peut_fabriquer, artisanat_texte, test_brut, test_carac_1_id, test_carac_2_id, equipement_brut, avantage_brut, origine, source_ref) VALUES ('metiers/flechier', 'Fléchier', 'flechier', 'Le fléchier fabrique flèches, carreaux et projectiles divers pour archers et arbalétriers. Il sélectionne plumes, bois et pointes avec soin. Ce métier demande patience, minutie et une bonne compréhension des besoins martiaux.', '+3% Arc OU Arbalète', 'Peut faire des flèches et carreaux mais aussi les arcs et arbalètes [FORCE  + PERCEPTION]', 1, 'Peut faire des flèches et carreaux mais aussi les arcs et arbalètes', 'FORCE  + PERCEPTION', 'force', 'perception', 'Méga Carquois (équipement)', 'Analyser des flèches, …', 'docs_typees', 'Google Doc « MÉTIER » › Fléchier › champs de la page');
INSERT INTO metier (id, nom, nom_cle, description, bonus_brut, artisanat_brut, peut_fabriquer, artisanat_texte, test_brut, test_carac_1_id, test_carac_2_id, equipement_brut, avantage_brut, origine, source_ref) VALUES ('metiers/forgeron', 'Forgeron', 'forgeron', 'Le forgeron transforme métal brut en armes, outils et pièces robustes. Sa maîtrise du feu et du marteau est au cœur de toute économie artisanale. Les soldats, paysans et artisans dépendent de son savoir-faire.', '+3% Arme lourde OU Arme légère', 'Peut faire des armes métalliques [FORCE  + VOLONTÉ]', 1, 'Peut faire des armes métalliques', 'FORCE  + VOLONTÉ', 'force', 'volonte', 'Kit de réparation d’arme, Maillet en fer', 'Identifier une arme, …', 'docs_typees', 'Google Doc « MÉTIER » › Forgeron › champs de la page');
INSERT INTO metier (id, nom, nom_cle, description, bonus_brut, artisanat_brut, peut_fabriquer, artisanat_texte, test_brut, test_carac_1_id, test_carac_2_id, equipement_brut, avantage_brut, origine, source_ref) VALUES ('metiers/fossoyeur', 'Fossoyeur', 'fossoyeur', 'Le fossoyeur creuse tombes, entretient les cimetières et veille au respect des défunts. Il travaille souvent seul, loin de l’agitation des villages. Sa présence est discrète mais essentielle pour la dignité des morts.', '+3% Calme, +2% Intimidation', 'Rien', 0, NULL, NULL, NULL, NULL, 'Pelle OU faucille en acier (arme)', 'Observer un cimetière, déterrer quelque chose, …', 'docs_typees', 'Google Doc « MÉTIER » › Fossoyeur › champs de la page');
INSERT INTO metier (id, nom, nom_cle, description, bonus_brut, artisanat_brut, peut_fabriquer, artisanat_texte, test_brut, test_carac_1_id, test_carac_2_id, equipement_brut, avantage_brut, origine, source_ref) VALUES ('metiers/garde-de-ville', 'Garde de ville', 'garde-de-ville', 'Le garde de ville maintient l’ordre dans les rues, protège les habitants et fait appliquer les lois locales. Il patrouille quotidiennement, observe les mouvements suspects et intervient en cas de trouble. Son uniforme est un symbole d’autorité pour la population.', '+2% Arme lourde OU Arme légère OU Arc OU Arbalète OU Parade OU Esquive', 'Rien', 0, NULL, NULL, NULL, NULL, 'Bouclier rond amalgame (bois+fer+fer) avec emblème de province', 'Reconnaître un grade, reconnaître une guilde, …', 'docs_typees', 'Google Doc « MÉTIER » › Garde de ville › champs de la page');
INSERT INTO metier (id, nom, nom_cle, description, bonus_brut, artisanat_brut, peut_fabriquer, artisanat_texte, test_brut, test_carac_1_id, test_carac_2_id, equipement_brut, avantage_brut, origine, source_ref) VALUES ('metiers/garde-du-corps', 'Garde du corps', 'garde-du-corps', 'Le garde du corps assure la protection rapprochée d’une personne importante, souvent au prix de sa propre sécurité. Il doit allier vigilance, robustesse et sang-froid. Sa présence dissuade les agresseurs et rassure ceux qu’il protège.', '+3% Parade OU Esquive, +2% Observation', 'Rien', 0, NULL, NULL, NULL, NULL, 'Rien', '…', 'docs_typees', 'Google Doc « MÉTIER » › Garde du corps › champs de la page');
INSERT INTO metier (id, nom, nom_cle, description, bonus_brut, artisanat_brut, peut_fabriquer, artisanat_texte, test_brut, test_carac_1_id, test_carac_2_id, equipement_brut, avantage_brut, origine, source_ref) VALUES ('metiers/gladiateur', 'Gladiateur', 'gladiateur', 'Le gladiateur combat dans des arènes devant un public avide de spectacle. Il s’entraîne quotidiennement pour maîtriser différentes armes et techniques. Sa vie est faite de gloire, de risques constants et d’une discipline imposée par ses maîtres ou sa troupe.', '+2% Vigueur, +2% Stabilité', 'Rien', 0, NULL, NULL, NULL, NULL, 'Glaive lourd ou léger en acier (arme)', '…', 'docs_typees', 'Google Doc « MÉTIER » › Gladiateur › champs de la page');
INSERT INTO metier (id, nom, nom_cle, description, bonus_brut, artisanat_brut, peut_fabriquer, artisanat_texte, test_brut, test_carac_1_id, test_carac_2_id, equipement_brut, avantage_brut, origine, source_ref) VALUES ('metiers/herboriste', 'Herboriste', 'herboriste', 'L’herboriste collecte, prépare et vend plantes et remèdes naturels. Il connaît les herbes, leurs effets et leurs dangers avec soin. Son échoppe est souvent un lieu de passage pour malades, voyageurs ou curieux.', '+3% Vie en nature, +3% Distinction, +1 butin pour les ingrédients utiles en alchimie', 'Rien', 0, NULL, NULL, NULL, NULL, 'Rien', 'Identifier une plante, une créature plante, …', 'docs_typees', 'Google Doc « MÉTIER » › Herboriste › champs de la page');
INSERT INTO metier (id, nom, nom_cle, description, bonus_brut, artisanat_brut, peut_fabriquer, artisanat_texte, test_brut, test_carac_1_id, test_carac_2_id, equipement_brut, avantage_brut, origine, source_ref) VALUES ('metiers/joaillier', 'Joaillier', 'joaillier', 'Le joaillier travaille les gemmes précieuses et est capable de les raffinées. Son œil exercé et sa minutie déterminent la valeur de ses créations. Les nobles et marchands riches recherchent souvent ses services.', '+3% Observation, +3% Magie OU Concentration', 'Peut faire gemmes supérieur [PERCEPTION  + INTELLIGENCE]', 1, 'Peut faire gemmes supérieur', 'PERCEPTION  + INTELLIGENCE', 'perception', 'intelligence', 'Rien', 'Identifier les gemmes précieuses, …', 'docs_typees', 'Google Doc « MÉTIER » › Joaillier › champs de la page');
INSERT INTO metier (id, nom, nom_cle, description, bonus_brut, artisanat_brut, peut_fabriquer, artisanat_texte, test_brut, test_carac_1_id, test_carac_2_id, equipement_brut, avantage_brut, origine, source_ref) VALUES ('metiers/juge', 'Juge', 'juge', 'Le juge supervise les affaires juridiques, tranche les litiges et applique les lois de sa région. Son rôle exige équité, sang-froid et une grande connaissance des coutumes locales. Il symbolise la justice aux yeux du peuple.', '+3% Psychologie, +3% Intimidation, +3% Diplomatie', 'Rien', 0, NULL, NULL, NULL, NULL, 'Rien', '…', 'docs_typees', 'Google Doc « MÉTIER » › Juge › champs de la page');
INSERT INTO metier (id, nom, nom_cle, description, bonus_brut, artisanat_brut, peut_fabriquer, artisanat_texte, test_brut, test_carac_1_id, test_carac_2_id, equipement_brut, avantage_brut, origine, source_ref) VALUES ('metiers/libraire', 'Libraire', 'libraire', 'Le libraire copie, relie et distribue manuscrits et ouvrages pour érudits et voyageurs. Il travaille avec soin sur les textes, veillant à leur lisibilité et à leur préservation. Son atelier est un refuge pour ceux qui aiment les histoires et le savoir.', '+6% Connaissance', 'Rien', 0, NULL, NULL, NULL, NULL, 'Rien', 'Identifier un livre, …', 'docs_typees', 'Google Doc « MÉTIER » › Libraire › champs de la page');
INSERT INTO metier (id, nom, nom_cle, description, bonus_brut, artisanat_brut, peut_fabriquer, artisanat_texte, test_brut, test_carac_1_id, test_carac_2_id, equipement_brut, avantage_brut, origine, source_ref) VALUES ('metiers/macon', 'Maçon', 'macon', 'Le maçon érige murs, bâtiments et fondations qui structurent villages et cités. Il maîtrise la pierre, le mortier et les techniques d’assemblage. Son travail exige endurance, précision et un sens de la stabilité.', '+3% Athlétisme, +3% Stabilité', 'Peut aider à la construction d’un bâtiment [FORCE + AGILITÉ]', 1, 'Peut aider à la construction d’un bâtiment', 'FORCE + AGILITÉ', 'force', 'agilite', 'Rien', 'Observer un bâtiment, casser un mur, …', 'docs_typees', 'Google Doc « MÉTIER » › Maçon › champs de la page');
INSERT INTO metier (id, nom, nom_cle, description, bonus_brut, artisanat_brut, peut_fabriquer, artisanat_texte, test_brut, test_carac_1_id, test_carac_2_id, equipement_brut, avantage_brut, origine, source_ref) VALUES ('metiers/maitre-nageur', 'Maître-nageur', 'maitre-nageur', 'Le maître-nageur surveille rivières, bassins ou ports pour éviter les accidents et aider ceux en difficulté. Il connaît parfaitement les courants, les techniques de nage et les gestes de sauvetage. Sa vigilance protège voyageurs, pêcheurs et enfants.', '+3% Athlétisme OU Équilibre, +1 Vitesse nage', 'Rien', 0, NULL, NULL, NULL, NULL, 'Rien', NULL, 'docs_typees', 'Google Doc « MÉTIER » › Maître-nageur › champs de la page');
INSERT INTO metier (id, nom, nom_cle, description, bonus_brut, artisanat_brut, peut_fabriquer, artisanat_texte, test_brut, test_carac_1_id, test_carac_2_id, equipement_brut, avantage_brut, origine, source_ref) VALUES ('metiers/marchand', 'Marchand', 'marchand', 'Le marchand parcours routes et marchés pour acheter, vendre et échanger toutes sortes de biens. Sa réussite dépend de son sens du commerce, de sa capacité à négocier et de son réseau. Il relie les villages entre eux et fait circuler richesses et nouvelles.', '+6% Négociation', 'Rien', 0, NULL, NULL, NULL, NULL, 'Gros sac à dos', '…', 'docs_typees', 'Google Doc « MÉTIER » › Marchand › champs de la page');
INSERT INTO metier (id, nom, nom_cle, description, bonus_brut, artisanat_brut, peut_fabriquer, artisanat_texte, test_brut, test_carac_1_id, test_carac_2_id, equipement_brut, avantage_brut, origine, source_ref) VALUES ('metiers/marechal-ferrant', 'Maréchal-ferrant', 'marechal-ferrant', 'Le maréchal-ferrant ferre les chevaux, entretient leur équipement et contribue à la santé de leurs sabots. Son travail demande force, précision et un bon rapport avec les animaux. Il est indispensable dans toute communauté dépendante des montures.', '+2% Dressage', 'Peut fabriquer des armures pour montures [FORCE + INTELLIGENCE]', 1, 'Peut fabriquer des armures pour montures', 'FORCE + INTELLIGENCE', 'force', 'intelligence', 'Kit de réparation d’armure', 'Réparer du matos pour familier, …', 'docs_typees', 'Google Doc « MÉTIER » › Maréchal-ferrant › champs de la page');
INSERT INTO metier (id, nom, nom_cle, description, bonus_brut, artisanat_brut, peut_fabriquer, artisanat_texte, test_brut, test_carac_1_id, test_carac_2_id, equipement_brut, avantage_brut, origine, source_ref) VALUES ('metiers/marin', 'Marin', 'marin', 'Le marin navigue sur les fleuves, les lacs ou les mers, participant aux manœuvres, au transport et à la survie de l’équipage. Il connaît les vents, les courants et les dangers liés à la navigation. Sa vie est faite de voyages, de discipline et d’histoires partagées entre marins.', '+3% Orientation, +3% Vie de nature', 'Rien', 0, NULL, NULL, NULL, NULL, 'Longue-vue', 'Piloter un navire, …', 'docs_typees', 'Google Doc « MÉTIER » › Marin › champs de la page');
INSERT INTO metier (id, nom, nom_cle, description, bonus_brut, artisanat_brut, peut_fabriquer, artisanat_texte, test_brut, test_carac_1_id, test_carac_2_id, equipement_brut, avantage_brut, origine, source_ref) VALUES ('metiers/maroquinier', 'Maroquinier', 'maroquinier', 'Le maroquinier travaille les cuirs pour créer sacs, ceintures, étuis et armures. Il sélectionne et traite les peaux avec soin pour obtenir des pièces durables. Ses créations sont utiles pour un peu tout le monde.', '+2% Esquive, +1AP donné par les armures cuir, peau, cellulose, corail, écaille fabriqués', 'Peut faire des armures peau, cuir, cellulose, corail, écaille [AGILITÉ  + INTELLIGENCE]', 1, 'Peut faire des armures peau, cuir, cellulose, corail, écaille', 'AGILITÉ  + INTELLIGENCE', 'agilite', 'intelligence', 'Kit de réparation d’armure', 'Identifier une arme, …', 'docs_typees', 'Google Doc « MÉTIER » › Maroquinier › champs de la page');
INSERT INTO metier (id, nom, nom_cle, description, bonus_brut, artisanat_brut, peut_fabriquer, artisanat_texte, test_brut, test_carac_1_id, test_carac_2_id, equipement_brut, avantage_brut, origine, source_ref) VALUES ('metiers/medecin', 'Médecin', 'medecin', 'Le médecin soigne les malades, étudie les symptômes et applique les traitements connus de son époque. Il doit garder son sang-froid face aux blessures comme aux maladies graves. Son savoir en fait une figure respectée, parfois crainte pour ses connaissances rares.', '+6% Médecine, Remonte la santé à 1 lors d’une stabilisation', 'Rien', 0, NULL, NULL, NULL, NULL, 'Sac de médecin, scalpel en fer', 'Soigner quelqu’un, identifier une maladie, …', 'docs_typees', 'Google Doc « MÉTIER » › Médecin › champs de la page');
INSERT INTO metier (id, nom, nom_cle, description, bonus_brut, artisanat_brut, peut_fabriquer, artisanat_texte, test_brut, test_carac_1_id, test_carac_2_id, equipement_brut, avantage_brut, origine, source_ref) VALUES ('metiers/menuisier', 'Menuisier', 'menuisier', 'Le menuisier façonne le bois pour fabriquer meubles, portes, coffres et objets du quotidien. Son talent se mesure à la finesse de ses assemblages et à la solidité de ses créations. Il travaille souvent dans un atelier où résonnent scies et rabots. Il est également utile pour travailler le bois magique pour faire les montures de bâtons magiques.', '+3% Athlétisme', 'Peut faire les montures de bâtons magiques, armure et bouclier en bois [FORCE  + INTELLIGENCE]', 1, 'Peut faire les montures de bâtons magiques, armure et bouclier en bois', 'FORCE  + INTELLIGENCE', 'force', 'intelligence', 'Écu de bois', 'Identifier un bois, …', 'docs_typees', 'Google Doc « MÉTIER » › Menuisier › champs de la page');
INSERT INTO metier (id, nom, nom_cle, description, bonus_brut, artisanat_brut, peut_fabriquer, artisanat_texte, test_brut, test_carac_1_id, test_carac_2_id, equipement_brut, avantage_brut, origine, source_ref) VALUES ('metiers/mineur', 'Mineur', 'mineur', 'Le mineur descend dans les entrailles de la terre pour extraire minerais, pierres et ressources rares. Son travail est dangereux, marqué par l''obscurité, la poussière et les risques d''effondrement. Sans lui, de nombreux artisans manqueraient de matériaux essentiels.', '+2% Observation, +2% Vigueur', 'Rien', 0, NULL, NULL, NULL, NULL, 'Démarre avec une pioche en acier (arme)', 'Se repérer dans une mine, reconnaître une pierre, …', 'docs_typees', 'Google Doc « MÉTIER » › Mineur › champs de la page');
INSERT INTO metier (id, nom, nom_cle, description, bonus_brut, artisanat_brut, peut_fabriquer, artisanat_texte, test_brut, test_carac_1_id, test_carac_2_id, equipement_brut, avantage_brut, origine, source_ref) VALUES ('metiers/monstrologue', 'Monstrologue', 'monstrologue', 'Le monstrologue étudie les créatures du monde, observant leur comportement, leurs habitats et leurs particularités. Il parcourt souvent régions sauvages et terres reculées pour collecter des informations précieuses. Ses écrits aident aventuriers, chasseurs et érudits à mieux comprendre ces êtres.', '+2% Connaissance, +2% Vie en nature, +2% Dressage.', 'Rien', 0, NULL, NULL, NULL, NULL, 'Rien', 'Identifier une créature, …', 'docs_typees', 'Google Doc « MÉTIER » › Monstrologue › champs de la page');
INSERT INTO metier (id, nom, nom_cle, description, bonus_brut, artisanat_brut, peut_fabriquer, artisanat_texte, test_brut, test_carac_1_id, test_carac_2_id, equipement_brut, avantage_brut, origine, source_ref) VALUES ('metiers/musicien', 'Musicien', 'musicien', 'Le musicien joue de son instrument pour divertir, émouvoir ou accompagner cérémonies et fêtes. Il se déplace souvent de ville en ville avec une troupe ou en solitaire. Sa renommée dépend de son talent, de son charisme et de son sens du rythme.', '+6% Distinction', 'Rien', 0, NULL, NULL, NULL, NULL, 'Rien', 'Distinguer des sons, …', 'docs_typees', 'Google Doc « MÉTIER » › Musicien › champs de la page');
INSERT INTO metier (id, nom, nom_cle, description, bonus_brut, artisanat_brut, peut_fabriquer, artisanat_texte, test_brut, test_carac_1_id, test_carac_2_id, equipement_brut, avantage_brut, origine, source_ref) VALUES ('metiers/myciculteur', 'Myciculteur', 'myciculteur', 'Le myciculteur est spécialisé dans la culture, la récolte et l’étude des champignons. Il travaille souvent dans des environnements humides et sombres, maîtrisant les conditions nécessaires à leur croissance. Son savoir lui permet de distinguer les espèces comestibles, utiles ou dangereuses avec précision. (n’est pas relié à la champicer)', '+3% Connaissance, +3% Vie en nature', 'Rien', 0, NULL, NULL, NULL, NULL, 'Pelle en fer (Arme)', 'Information sur les champignons, …', 'docs_typees', 'Google Doc « MÉTIER » › Myciculteur › champs de la page');
INSERT INTO metier (id, nom, nom_cle, description, bonus_brut, artisanat_brut, peut_fabriquer, artisanat_texte, test_brut, test_carac_1_id, test_carac_2_id, equipement_brut, avantage_brut, origine, source_ref) VALUES ('metiers/patissier', 'Pâtissier', 'patissier', 'Le pâtissier prépare desserts, viennoiseries et douceurs pour ceux qui sont aisés,les tavernes prestigieuses ou les banquets. Il maîtrise les techniques de cuisson, de décoration et de présentation pour créer des produits à la fois savoureux et esthétiques. Leur travail est souvent comparé à ceux d’un artiste, de ceux qui vénère Bauc.', '+2% Distinction, +2% Diplomatie', 'Fabriquer des douceurs, ces derniers peut redonner 5 barrière si consommé [INTELLIGENCE + PERCEPTION]', 1, 'Fabriquer des douceurs, ces derniers peut redonner 5 barrière si consommé', 'INTELLIGENCE + PERCEPTION', 'intelligence', 'perception', 'Rien', 'Identifier les gâteaux, parler avec les nobles, …', 'docs_typees', 'Google Doc « MÉTIER » › Pâtissier › champs de la page');
INSERT INTO metier (id, nom, nom_cle, description, bonus_brut, artisanat_brut, peut_fabriquer, artisanat_texte, test_brut, test_carac_1_id, test_carac_2_id, equipement_brut, avantage_brut, origine, source_ref) VALUES ('metiers/peintre', 'Peintre', 'peintre', 'Le peintre capture scènes, portraits et paysages sur toile ou panneau de bois. Son regard attentif et son sens des couleurs dictent la qualité de ses œuvres. Il travaille parfois sur commande, parfois par passion, cherchant à immortaliser le monde tel qu’il le voit.', '+6% Observation', 'Peut dessiner quelque chose [PERCEPTION x2]', 1, 'Peut dessiner quelque chose', 'PERCEPTION x2', NULL, NULL, 'Parchemin vierge, plume', 'Observer une peinture, …', 'docs_typees', 'Google Doc « MÉTIER » › Peintre › champs de la page');
INSERT INTO metier (id, nom, nom_cle, description, bonus_brut, artisanat_brut, peut_fabriquer, artisanat_texte, test_brut, test_carac_1_id, test_carac_2_id, equipement_brut, avantage_brut, origine, source_ref) VALUES ('metiers/politicien', 'Politicien', 'politicien', 'Le politicien participe aux décisions d’une cité, d’un comté ou d’un royaume en influençant lois et orientations locales. Il maîtrise l''art du discours, des alliances et des compromis. Sa carrière dépend autant de ses compétences que de sa capacité à se faire apprécier ou craindre.', '+3% Diplomatie, +3% Manipulation', 'Rien', 0, NULL, NULL, NULL, NULL, 'Rien', '…', 'docs_typees', 'Google Doc « MÉTIER » › Politicien › champs de la page');
INSERT INTO metier (id, nom, nom_cle, description, bonus_brut, artisanat_brut, peut_fabriquer, artisanat_texte, test_brut, test_carac_1_id, test_carac_2_id, equipement_brut, avantage_brut, origine, source_ref) VALUES ('metiers/prostitue', 'Prostitué', 'prostitue', 'La prostituée offre ses services contre paiement, accueillant clients dans des établissements, des quartiers dédiés ou lors de déplacements. C’est un métier à risque et la quasi intégralité de ceux qui pratique ce métier ne l’ont pas fait volontairement.', '+3% Manipulation, Survie', 'Rien', 0, NULL, NULL, NULL, NULL, 'Rien', 'Attirer l’attention de quelqu’un, …', 'docs_typees', 'Google Doc « MÉTIER » › Prostitué › champs de la page');
INSERT INTO metier (id, nom, nom_cle, description, bonus_brut, artisanat_brut, peut_fabriquer, artisanat_texte, test_brut, test_carac_1_id, test_carac_2_id, equipement_brut, avantage_brut, origine, source_ref) VALUES ('metiers/sapeur', 'Sapeur', 'sapeur', 'Le sapeur est spécialisé dans la manipulation du feu, de la poudre ou dans la mise en place de structures destinées à affaiblir ou détruire des fortifications. Souvent envoyé en première ligne lors des sièges, il travaille avec précision et sang-froid. Malgré les risques, son expertise est indispensable pour créer des brèches, poser des pièges ou sécuriser certains ouvrages.', '+3% Arme lourde OU Arme légère', 'Peut faire des bombes, des armes de sièges [PERCEPTION  + INTELLIGENCE]', 1, 'Peut faire des bombes, des armes de sièges', 'PERCEPTION  + INTELLIGENCE', 'perception', 'intelligence', 'Gros sac de bombe, Hache du sapeur en fer', 'Identifier une bombe, repérer une zone à risque, identifier une arme de siège, …', 'docs_typees', 'Google Doc « MÉTIER » › Sapeur › champs de la page');
INSERT INTO metier (id, nom, nom_cle, description, bonus_brut, artisanat_brut, peut_fabriquer, artisanat_texte, test_brut, test_carac_1_id, test_carac_2_id, equipement_brut, avantage_brut, origine, source_ref) VALUES ('metiers/savant', 'Savant', 'savant', 'Le savant consacre sa vie à l’étude, aux expériences et à la compréhension du monde. Souvent entouré de livres, d’outils étranges ou de notes gribouillées, il cherche constamment de nouvelles réponses aux questions que d’autres ne se posent même pas. Sa curiosité peut le mener aussi bien dans les bibliothèques que sur le terrain pour observer, mesurer ou analyser.', '+6% Connaissance', 'Rien', 0, NULL, NULL, NULL, NULL, 'Rien', 'Savoir quelque chose, …', 'docs_typees', 'Google Doc « MÉTIER » › Savant › champs de la page');
INSERT INTO metier (id, nom, nom_cle, description, bonus_brut, artisanat_brut, peut_fabriquer, artisanat_texte, test_brut, test_carac_1_id, test_carac_2_id, equipement_brut, avantage_brut, origine, source_ref) VALUES ('metiers/scribe', 'Scribe', 'scribe', 'Le scribe maîtrise l’écriture, la lecture et la copie de documents officiels, religieux ou commerciaux. Souvent sollicité par ceux qui ne savent pas écrire, il consigne contrats, lettres ou récits avec précision. Son travail exige patience, rigueur et une grande attention aux détails.', '+10% de bonus à la création de documents', 'Peut créer des parchemin gravé et mettre des sorts dedans [Artisanat SOCIAL + INTELLIGENCE]', 1, 'Peut créer des parchemin gravé et mettre des sorts dedans', 'Artisanat SOCIAL + INTELLIGENCE', NULL, NULL, 'Plume à graver, encrier', 'Identifier des documents, identifier une langue, …', 'docs_typees', 'Google Doc « MÉTIER » › Scribe › champs de la page');
INSERT INTO metier (id, nom, nom_cle, description, bonus_brut, artisanat_brut, peut_fabriquer, artisanat_texte, test_brut, test_carac_1_id, test_carac_2_id, equipement_brut, avantage_brut, origine, source_ref) VALUES ('metiers/sculpteur', 'Sculpteur', 'sculpteur', 'Le sculpteur façonne la pierre, le bois ou l’os pour créer des statues, des décorations ou des objets utilitaires. Armé de burins et d’outils précis, il transforme la matière brute en formes harmonieuses.', '+2% Observation, +2% Concentration, +2% Athlétisme', 'Peut fabriquer des armes en os et armures en corne/os [FORCE + INTELLIGENCE]', 1, 'Peut fabriquer des armes en os et armures en corne/os', 'FORCE + INTELLIGENCE', 'force', 'intelligence', 'Dague en acier (Arme)', 'Identifier des os, des écailles, un golem …', 'docs_typees', 'Google Doc « MÉTIER » › Sculpteur › champs de la page');
INSERT INTO metier (id, nom, nom_cle, description, bonus_brut, artisanat_brut, peut_fabriquer, artisanat_texte, test_brut, test_carac_1_id, test_carac_2_id, equipement_brut, avantage_brut, origine, source_ref) VALUES ('metiers/serrurier', 'Serrurier', 'serrurier', 'Le serrurier conçoit, fabrique et répare serrures, cadenas et mécanismes de verrouillage. Méticuleux et ingénieux, il travaille souvent sur des pièces petites mais complexes qui exigent une main sûre. On fait appel à lui aussi bien pour sécuriser un coffre que pour ouvrir une porte close.', '+3% Ruse, +3% Sabotage, réduit de 1d4 le niveau d’une serrure, porte, coffre.', 'Rien', 0, NULL, NULL, NULL, NULL, 'Crochet (x3)', 'Identifier une serrure, une porte, …', 'docs_typees', 'Google Doc « MÉTIER » › Serrurier › champs de la page');
INSERT INTO metier (id, nom, nom_cle, description, bonus_brut, artisanat_brut, peut_fabriquer, artisanat_texte, test_brut, test_carac_1_id, test_carac_2_id, equipement_brut, avantage_brut, origine, source_ref) VALUES ('metiers/serveur', 'Serveur', 'serveur', 'Le serveur travaille dans les auberges, tavernes ou maisons de thé, où il assure le service des clients. Rapide, attentif et doté d’une bonne mémoire, il doit jongler entre commandes, discussions animées et clients impatients. Son rôle lui permet souvent d’être au cœur des dernières rumeurs et des histoires du coin.', '+2% Diplomatie, +2% Distinction, +2% Esquive', 'Rien', 0, NULL, NULL, NULL, NULL, 'Rien', '…', 'docs_typees', 'Google Doc « MÉTIER » › Serveur › champs de la page');
INSERT INTO metier (id, nom, nom_cle, description, bonus_brut, artisanat_brut, peut_fabriquer, artisanat_texte, test_brut, test_carac_1_id, test_carac_2_id, equipement_brut, avantage_brut, origine, source_ref) VALUES ('metiers/tailleur-de-pierre', 'Tailleur de pierre', 'tailleur-de-pierre', 'Le tailleur de pierre extrait, coupe et façonne les blocs destinés aux bâtiments, ponts ou sculptures. Travaillant avec force et précision, il donne forme à la roche brute selon les besoins des architectes. Son savoir-faire est essentiel pour construire des structures solides et durables.', '+3% Observation, +3% Athlétisme', 'Rien', 0, NULL, NULL, NULL, NULL, 'Piolet en acier (arme)', 'Identifier un type de pierre, un sol, …', 'docs_typees', 'Google Doc « MÉTIER » › Tailleur de pierre › champs de la page');
INSERT INTO metier (id, nom, nom_cle, description, bonus_brut, artisanat_brut, peut_fabriquer, artisanat_texte, test_brut, test_carac_1_id, test_carac_2_id, equipement_brut, avantage_brut, origine, source_ref) VALUES ('metiers/verger', 'Verger', 'verger', 'Le verger, ou arboriculteur, cultive et entretient les arbres fruitiers afin d’assurer une récolte abondante. Il surveille la croissance des arbres, taille les branches, protège les cultures et gère les saisons avec grand soin. Son travail nourrit villages et marchés grâce à une production patiente et régulière.', '+3% Connaissance, +3% Fermeté', 'Rien', 0, NULL, NULL, NULL, NULL, 'Faucille en acier (Arme)', 'Information sur les arbres cultivables, …', 'docs_typees', 'Google Doc « MÉTIER » › Verger › champs de la page');
